                if (header == 'COUNT') { // 헤더 값이 COUNT일때(셀아이디가 파일첨부일때)
                    if (!Number.isSafeInteger(Number(nValue))) { // COUNT셀의 값이 숫자가 아닐때 
                        Alert(Sepoa.cache.text.get("SLM_221.MSG_0041")); // 경고창
                        return false;
                    } else if (Number.isSafeInteger(Number(nValue))) { // COUNT셀의 값이 숫자일때
                        if (nValue <= 0) { // 0보다 작을경우
